const $=s=>document.querySelector(s),C=DojoCourse,words=C.VOCAB,values=C.VALUES;
let key='san-dojo-v1',appReady=false;
const defaults=()=>({xp:0,completed:[],days:[],rewards:{},sessions:{},game:G.create(),learning:C.initial(),media:{}});
let state=defaults(),storageOK=true,currentView='home',currentModule='dojo',active=null,currentAudio=null;
// O administrador na faixa preta pode revisar qualquer fase sem fabricar aprovações.
const adminPreview=()=>appReady&&DojoAccounts.canManage()&&state.game.belt===12;
const standardModuleUnlocked=C.moduleUnlocked,standardPhaseUnlocked=C.phaseUnlocked;
C.moduleUnlocked=(progress,id)=>Boolean(C.moduleById(id))&&(adminPreview()||standardModuleUnlocked(progress,id));
C.phaseUnlocked=(progress,id)=>Boolean(C.phaseById(id))&&(adminPreview()||standardPhaseUnlocked(progress,id));
try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&Array.isArray(saved.completed)&&Array.isArray(saved.days)&&Number.isFinite(saved.xp))state={...defaults(),...saved};}catch{storageOK=false;}
if(!state.game||state.game.version!==1||!state.game.energy||!state.game.weeks||!Array.isArray(state.game.history)||!Number.isInteger(state.game.belt)||state.game.belt<0||state.game.belt>12)state.game=G.create();
if(!state.learning||state.learning.version!==1||!state.learning.phases||!state.learning.approvals)state.learning=C.initial();
if(!state.media||typeof state.media!=='object'||Array.isArray(state.media))state.media={};
state.game.highestBelt=Math.max(state.game.belt,Number(state.game.highestBelt)||0);
state.game.requireMastery=true;state.game.mastery??={};state.game.masteryFromWeek??=G.weekKey();
T.syncMastery(state.learning,state.game);
const settledWeeks=G.reconcile(state.game);state.learning.availableBelt=state.game.belt;
if(state.game.pendingEnergy){G.refund(state.game);state.game.pendingEnergy=false;}
function save(){T.syncMastery(state.learning,state.game);try{localStorage.setItem(key,JSON.stringify(state));if(appReady)DojoAccounts.queueProgress(state);}catch{storageOK=false;toast('O navegador não permitiu salvar o progresso. Esta sessão continua disponível.');}}
function dayKey(){return G.dayKey();}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',5500);}
function streak(){return streakSummary().current;}
function stats(){$('#xp').textContent=state.xp;$('#streak').textContent=streak();const unlimited=G.unlimited(state.game);$('#energy-count').textContent=unlimited?'∞':G.refill(state.game);$('#energy-button').setAttribute('aria-label',unlimited?'Energia ilimitada. Ver informações':`Energia: ${state.game.energy.count} de ${G.RULES.maxEnergy}. Ver recarga`);$('#energy-button').classList.toggle('unlimited',unlimited);$('#sidebar-belt').innerHTML=beltArt(state.game.belt,true);$('#sidebar-belt-name').textContent=G.BELTS[state.game.belt].name;}
let sequencePlayback=0;
function stopAudio(){sequencePlayback++;DojoFeedback.stop();if(currentAudio){currentAudio.onended=null;currentAudio.onerror=null;currentAudio.pause();currentAudio=null;}if('speechSynthesis'in window)speechSynthesis.cancel();}
function speak(name,slow=false){stopAudio();const item=JAPANESE_AUDIO[name];if(item){currentAudio=$('#japanese-player');currentAudio.src=item.src;currentAudio.playbackRate=slow?.7:1;currentAudio.play().catch(()=>toast('Não foi possível tocar o áudio. Tente novamente ou verifique o som do dispositivo.'));return;}const word=words.find(w=>w.name===name),voice=window.speechSynthesis?.getVoices().find(v=>v.lang.startsWith('ja'));if(word&&voice){const u=new SpeechSynthesisUtterance(word.say);u.lang='ja-JP';u.voice=voice;u.rate=slow?.55:.8;speechSynthesis.speak(u);}else toast('Áudio indisponível para este termo.');}
function speakSequence(names,slow=false){stopAudio();const token=sequencePlayback,player=$('#japanese-player');let index=0;function next(){if(token!==sequencePlayback||index>=names.length)return;const item=JAPANESE_AUDIO[names[index++]];if(!item){toast('Um áudio desta sequência está indisponível.');return;}currentAudio=player;player.src=item.src;player.playbackRate=slow?.7:1;player.onended=()=>setTimeout(next,slow?650:400);player.onerror=()=>toast('Não foi possível tocar a sequência. Tente novamente.');player.play().catch(()=>toast('Toque em ouvir novamente para iniciar o áudio.'));}next();}
function audioButtons(name,quiz=false){return `<div class="audio-buttons"><button type="button" class="audio" data-speak="${esc(name)}" aria-label="${quiz?'Ouvir áudio do desafio':'Ouvir '+esc(name)}">◖)) &nbsp; ${quiz?'Ouvir desafio':esc(name)}</button><button type="button" class="audio slow-audio" data-speak="${esc(name)}" data-slow aria-label="${quiz?'Ouvir desafio mais devagar':'Ouvir '+esc(name)+' mais devagar'}">0,7× · Devagar</button></div>`;}
function passedCount(){return C.COURSE.reduce((n,m)=>n+m.phases.filter(p=>state.learning.phases[p.id]?.passed).length,0);}
function moduleCard(m){const unlocked=C.moduleUnlocked(state.learning,m.id),count=m.phases.filter(p=>state.learning.phases[p.id]?.passed).length,done=C.moduleComplete(state.learning,m.id),awaiting=C.moduleQuizPassed(state.learning,m.id)&&!done;return `<button class="module-card ${unlocked?'':'module-locked'} ${done?'module-complete':''}" data-module="${m.id}" aria-label="Módulo ${m.level}: ${m.title}. ${done?'Concluído':unlocked?'Disponível':'Bloqueado para atividades'}"><span class="module-number">${String(m.level).padStart(2,'0')}</span><span class="module-glyph">${m.icon}</span><div><span class="difficulty-label">NÍVEL ${m.level} · META ${m.pass}%</span><h3>${m.title}</h3><p>${m.subtitle}</p><div class="module-track"><span style="width:${count/4*100}%"></span></div><small>${awaiting?'Conferência do sensei pendente':done?'✓ Módulo concluído':`${count} / 4 fases aprovadas`}</small></div><span class="module-arrow">${done?'✓':unlocked?'→':'⌑'}</span></button>`;}
function home(){if(DojoAccounts.configured&&!DojoAccounts.localPreview&&!DojoAccounts.user)return DojoPublicHome;const next=C.nextPhase(state.learning),today=dayKey(),todayXP=(state.rewards[today]?.length||0)*20;return `<section class="animate-in"><div class="eyebrow">APRENDER, PRATICAR, EVOLUIR</div><h1>Osu, pequeno karateca! ✦</h1><p class="intro">Cada fase pede uma nova descoberta. Cada módulo, mais atenção.</p><div class="hero"><div class="hero-copy"><span class="tag">32 MÓDULOS · 102 FASES · UM PASSO DE CADA VEZ</span><h2>Seu karate cresce<br>com você.</h2><p>Escute em japonês, observe os movimentos e mostre o que aprendeu.</p>${next?`<button class="primary" data-phase="${next.id}">${passedCount()?'Continuar minha fase':'Começar a primeira fase'} <span>→</span></button>`:`<button class="primary" data-view="practice">Revisar minha jornada <span>→</span></button>`}</div><div class="hero-art">${mentor()}<div class="speech">Vamos aprender de verdade. OSS!</div></div></div>${trainingOverview()}<div class="dashboard"><div><div class="section-head"><h2>Módulos fundamentais</h2><span class="tiny">${passedCount()} / 24 fases</span></div><div class="learning-callout"><b>Mais conhecimento, menos pistas.</b><p>A nota considera a primeira resposta. As fases precisam de ${C.COURSE[0].pass}% a 90% de acertos para liberar o próximo passo.</p></div><div class="course-list">${C.COURSE.map(moduleCard).join('')}</div><p class="under-trail">Avance no app pelas fases aprovadas, sem liberação manual.<br>Pratique os movimentos com orientação presencial.</p></div><aside class="right-col">${streakWidget()}${weeklyTrainingWidget()}<div class="side-card"><div class="side-title"><h3>Sua meta de hoje</h3><span>✦</span></div><div class="goal-main">${Math.min(todayXP,40)} <small>/ 40 XP</small></div><p>${todayXP>=40?'Meta alcançada! Continue no seu ritmo.':'Duas fases aprovadas valem 40 XP.'}</p><div class="track"><span style="width:${Math.min(100,todayXP/40*100)}%"></span></div></div><div class="side-card"><h3>Ouvir. Observar. Praticar.</h3><p>Áudios japoneses incluídos, vídeos de referência e esquemas de apoio em cada etapa.</p><button class="outline" data-view="words">Abrir palavras do dojo →</button></div></aside></div></section>`;}
function phaseRow(m,p,i){const record=state.learning.phases[p.id],unlocked=C.phaseUnlocked(state.learning,p.id);return `<button class="phase-row ${record?.passed?'phase-passed':''} ${unlocked?'':'phase-locked'}" data-phase="${p.id}" aria-label="Fase ${i+1}: ${p.title}. ${record?.passed?'Aprovada':unlocked?'Disponível':'Bloqueada'}"><span class="phase-node">${record?.passed?'✓':i+1}</span><div><span class="difficulty-label">${p.exam?'DESAFIO DO MÓDULO':'FASE '+(i+1)} · ${p.questionIds.length} QUESTÕES</span><h3>${p.title}</h3><p>${p.desc}</p><small>${record?`Melhor nota: ${record.best}% · ${record.attempts} tentativa(s)`:`Meta: ${m.pass}% de acertos de primeira`}</small></div><span>${record?.passed?'Revisar':unlocked?'→':'⌑'}</span></button>`;}
function modulePage(){const m=C.moduleById(currentModule)||C.COURSE[0],unlocked=C.moduleUnlocked(state.learning,m.id),done=C.moduleQuizPassed(state.learning,m.id);return `<section class="animate-in"><button class="back-link" data-view="home">← Voltar à trilha</button><div class="eyebrow">${m.kind==='training'?(m.type==='kihon'?'KIHON':'IDO GEIKO')+' · FAIXA '+G.BELTS[m.belt].name:'MÓDULO '+m.level+' · DIFICULDADE '+m.level+' DE 6'}</div><h1>${m.title}</h1><p class="intro">${m.subtitle} · mínimo de ${m.pass}% em cada fase.</p>${!unlocked?`<div class="learning-callout"><b>As atividades deste módulo ainda estão bloqueadas.</b><p>${m.kind==='training'?'Você pode consultar o material. Os desafios serão liberados quando sua faixa do app chegar a '+G.BELTS[m.belt].name+'.':'Você pode consultar o material. Para fazer as atividades, aprove as fases do módulo anterior.'}</p></div>`:''}${m.id==='kata'?'<div class="catalog-link"><button class="outline" data-view="katas">Abrir catálogo com os 23 nomes de katas →</button></div>':''}<div class="module-layout"><div><div class="phase-list">${m.phases.map((p,i)=>phaseRow(m,p,i)).join('')}</div>${m.requiresSensei?`<div class="practical-gate"><span>🥋</span><div><h3>${state.learning.approvals[m.id]?'Conferência prática registrada':'Depois do desafio: mostrar ao sensei'}</h3><p>${state.learning.approvals[m.id]?esc(state.learning.approvals[m.id].note||'O registro local da prática foi feito.'):done?'As fases digitais foram aprovadas. O próximo módulo espera a observação e o registro do sensei.':'O sensei observa os movimentos e as correções antes de liberar o próximo módulo.'}</p><ul>${m.practical.map(p=>`<li>${p}</li>`).join('')}</ul></div></div>`:''}</div><div class="module-material"><h2>Prepare o olhar e a escuta</h2>${m.notes.map(n=>`<p>${n}</p>`).join('')}<div class="module-vocabulary">${m.words.map(w=>audioButtons(w)).join('')}</div>${mediaMarkup(m.phases[0].id)}<div class="more-phase-media">${m.phases.slice(1).filter(p=>state.media[p.id]).map(p=>`<h3>Material da fase: ${p.title}</h3>${mediaMarkup(p.id)}`).join('')}</div></div></div></section>`;}
function practice(){const available=C.COURSE.flatMap(m=>m.phases).filter(p=>C.phaseUnlocked(state.learning,p.id));return `<section class="animate-in"><div class="eyebrow">REVISAR TAMBÉM É EVOLUIR</div><h1>Hora de praticar</h1>${trainingOverview()}<p class="intro">Reveja o que errou e fortaleça a memória.</p><div class="practice-banner"><h2>Seu próximo treino de memória</h2><p>Um desafio escolhe uma fase disponível. Os pontos vêm apenas com a nota mínima. Cada revisão usa 5 energias.</p><button class="primary" data-review>Escolher uma revisão →</button></div><div class="phase-list">${available.map(p=>phaseRow(C.phaseById(p.id).module,p,C.phaseById(p.id).module.phases.indexOf(p))).join('')}</div><p class="under-trail">25 energias · 5 por atividade · recarga automática.<br>Cada fase aprovada vale 20 XP uma vez por dia.</p></section>`;}
function glossary(){return `<section class="animate-in"><div class="eyebrow">VOZ JAPONESA INCLUÍDA NO APP</div><h1>Palavras do dojo</h1><p class="intro">Ouça, repita e compare. Use o botão devagar quando precisar.</p><div class="catalog-link"><button class="outline" data-view="kihon-audio">Ouvir Kihon: Te, Ashi, Shuto e Uke waza →</button></div><div class="catalog-link"><button class="outline" data-view="katas">Ver os 23 nomes de katas e ouvir a pronúncia →</button></div><nav class="words-jump" aria-label="Seções das palavras do dojo"><a href="#words" data-words-section="words-basics">Vocabulário</a><a href="#words" data-words-section="words-katas">23 katas</a><a href="#words" data-words-section="words-dojo-kun">Juramento</a></nav><h2 id="words-basics">Vocabulário do dojo</h2><div class="word-grid">${words.map(w=>`<article class="word-card"><div class="japanese" lang="ja">${w.jp}</div><h3>${w.name}</h3><p>${w.meaning}</p>${audioButtons(w.name)}</article>`).join('')}</div><p class="under-trail">Áudios sintetizados em japonês, voz Keita, incluídos neste aplicativo.<br>A fala da criança não é gravada nem avaliada automaticamente.</p>${kataWords()}${dojoKunWords()}</section>`;}
function awards(){const count=passedCount(),complete=C.COURSE.filter(m=>C.moduleComplete(state.learning,m.id)).length,badges=[['🌱','Primeira fase','Aprove a primeira fase.',count>=1],['◖))','Ouvido atento','Aprove a fase Escutar e contar.',state.learning.phases['dojo-2']?.passed],['足','Bases aprendidas','Conclua as fases do módulo 2.',C.moduleComplete(state.learning,'bases')],['型','Sequência com sentido','Conclua as fases do módulo 5.',C.moduleComplete(state.learning,'kata')],['✦','Passo constante','Estude em três dias seguidos.',streak()>=3],['心','Jornada completa','Conclua as fases dos seis módulos.',complete===6]];return `<section class="animate-in"><div class="eyebrow">ESFORÇO QUE VIRA APRENDIZADO</div><h1>Suas conquistas</h1><p class="intro">As medalhas acompanham as fases aprovadas e a constância nos estudos.</p><div class="summary"><div><b>${state.xp} ✦</b><small>XP totais</small></div><div><b>${count}/24</b><small>Fases aprovadas</small></div><div><b>${complete}/6</b><small>Módulos concluídos</small></div></div><div class="awards-grid">${badges.map(b=>`<article class="award ${b[3]?'':'locked'}"><div class="medal">${b[0]}</div><h3>${b[1]}</h3><p>${b[2]}</p><small>${b[3]?'✓ Conquistada':'Por conquistar'}</small></article>`).join('')}</div><p class="under-trail">Faixas e medalhas são ilustrativas. A graduação real acontece no dojo.</p></section>`;}
function adults(){return `<section class="animate-in"><div class="eyebrow">APRENDER COM ACOMPANHAMENTO</div><h1>Para responsáveis e senseis</h1><p class="intro">Uma trilha com estudo, memória e prática observada.</p><div class="info-panel"><h2>Como o aluno avança</h2><p>A trilha fundamental tem seis módulos com quatro fases cada. O treino por faixa acrescenta 26 módulos separados de Kihon e Ido geiko, com 78 fases e metas de até 95%. As atividades passam de reconhecimento a escuta, escrita de termos, ordenação e revisão acumulada. A primeira resposta conta para a nota; corrigir depois de uma explicação ajuda na revisão, sem aumentar aquela nota.</p><p>A aprovação exige de 75% a 90%, conforme o módulo. Sem a nota, a fase seguinte continua bloqueada. O próximo módulo é liberado automaticamente quando as fases anteriores são aprovadas.</p><p>A entrada e o avanço digital não dependem de aprovação manual do administrador. O aplicativo não usa câmera nem avalia postura, execução ou pronúncia automaticamente. O currículo e as demonstrações devem ser ajustados ao ensino do San Dojo.</p><button class="primary" data-view="library">Abrir Biblioteca do sensei →</button></div>${freeAccessPanel()}${weeklyRulesPanel()}<div class="info-panel"><h2>Seus áudios, vídeos e imagens</h2><p>A voz japonesa está incluída como áudio sintetizado. Os vídeos de referência usam a internet; você pode substituí-los por seus próprios links e arquivos. Na versão conectada, vídeos MP4/WebM e imagens enviados pelo administrador ficam na biblioteca online para os alunos autenticados.</p><p>${DojoAccounts.configured?'O progresso é salvo na conta autenticada e carregado ao entrar com a mesma conta e provedor em outro aparelho.':'A prévia local guarda o progresso somente neste navegador. As contas ainda precisam ser conectadas.'} ${storageOK?'Há também um salvamento local neste navegador.':'O navegador está impedindo o salvamento local.'} Use a mesma conta em todos os aparelhos; não há atualização simultânea entre sessões abertas.</p><button class="outline danger" data-reset>Reiniciar somente o progresso do aluno</button><div id="reset-confirm"></div><p class="week-note">Seus materiais da biblioteca são preservados ao reiniciar o progresso.</p></div><div class="info-panel"><h2>Dojo Kun em palavras simples</h2><p>Adaptação educativa. A recitação oficial é a ensinada pelo sensei do San Dojo.</p><div class="dojo-values">${values.map((v,i)=>`<div class="value"><b>0${i+1}</b><p>${v}</p></div>`).join('')}</div></div></section>`;}
const views={home,sequence:sequencePage,practice,words:glossary,awards,adults,belts:trainingBeltJourney,library,module:modulePage,katas:kataCatalog,kata:kataPage,training:trainingPage,'kihon-audio':kihonAudio,kihon:kihonMaterialPage,account:accountPage};
const labels={sequence:'Minha sequência',home:'Minha jornada',practice:'Hora de praticar',words:'Palavras do dojo',awards:'Conquistas',adults:'Para responsáveis',belts:'Minhas faixas',library:'Biblioteca do sensei',module:'Módulo',katas:'Catálogo de katas',kata:'Kata',training:'Kihon e Ido geiko','kihon-audio':'Áudio do kihon',kihon:'Material do kihon',account:'Minha conta'};
function render(view){if(!appReady)return;view=DojoPublic.resolveView(DojoAccounts,view||currentView);document.body.classList.toggle('dojo-guest',Boolean(DojoAccounts.configured&&!DojoAccounts.localPreview&&!DojoAccounts.user));T.syncMastery(state.learning,state.game);if(G.reconcile(state.game).length)save();state.learning.availableBelt=state.game.belt;stopAudio();DojoMedia.clearUrls();if(view)currentView=views[view]?view:'home';$('#main').innerHTML=(adminPreview()?'<div class="learning-callout"><b>Teste do administrador · faixa preta</b><p>Todas as fases estão disponíveis para sua revisão. Nenhuma fase foi marcada como aprovada por este acesso.</p></div>':'')+views[currentView]();$('#page-label').textContent=currentView==='module'?C.moduleById(currentModule)?.title:labels[currentView];document.querySelectorAll('[data-view]').forEach(el=>{const selected=el.dataset.view===currentView||(currentView==='training'&&el.dataset.view==='practice')||(currentView==='kihon-audio'&&el.dataset.view==='words')||(currentView==='module'&&el.dataset.view==='home');el.classList.toggle('active',selected);if(selected)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});stats();hydrateMedia($('#main'));if(currentView==='library')prefillMaterial();if(currentView==='katas')filterKatas();if(currentView==='sequence')DojoPush.mount();}
function route(){if(!appReady)return;const [view,id]=location.hash.slice(1).split('/');if(view==='module'&&C.moduleById(id))currentModule=id;if(view==='kata'&&kataById(id))currentKata=id;if(view==='kihon'&&kihonMaterialById(id))currentKihonMaterial=id;if(view==='library'&&mediaTarget(id)){libraryModule=mediaTarget(id).module.id;libraryPhase=id;}render(view||'home');window.scrollTo({top:0});}
function go(path){if(location.hash==='#'+path)route();else location.hash=path;}
function shuffled(items){const out=[...items];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]];}return out;}
function startPhase(id){DojoFeedback.unlock();if(!DojoAccounts.canStudy()){go("account");return;}const found=C.phaseById(id);if(!found)return;state.learning.availableBelt=state.game.belt;if(!C.phaseUnlocked(state.learning,id)){toast('Aprove a fase anterior para continuar.');return;}const reservation=G.reserve(state.game);if(!reservation.allowed){openEnergy();return;}state.game.pendingEnergy=reservation.charged;save();stats();active={...found,deck:shuffled(found.phase.questionIds.map(q=>C.QUESTIONS[q])),index:-1,selected:null,order:[],tries:0,checked:false,correct:0,wrong:[],finished:false,charged:reservation.charged};renderQuestion();$('#lesson').showModal();}
function renderQuestion(){stopAudio();DojoMedia.clearUrls();const a=active;$('#feedback').textContent='';$('#feedback').className='';$('#answer').disabled=false;$('#lesson-bar').style.width=`${Math.max(0,a.index+1)/(a.deck.length+1)*100}%`;$('#lesson-count').textContent=`${Math.max(1,a.index+2)} / ${a.deck.length+1}`;$('#lesson-hint').textContent='A primeira resposta conta para sua nota.';if(a.index<0){$('#lesson-content').innerHTML=`<div class="eyebrow">MÓDULO ${a.module.level} · ${a.phase.exam?'DESAFIO':'PREPARAÇÃO'}</div><h2>${a.phase.title}</h2><p>${a.phase.desc}</p><div class="phase-goal"><b>${a.module.pass}% para aprovar</b><span>${a.deck.length} questões · 5 energias</span></div><div class="phase-study">${a.module.notes.map(n=>`<p>${n}</p>`).join('')}</div><div class="module-vocabulary">${a.module.words.slice(0,4).map(w=>audioButtons(w)).join('')}</div>${mediaMarkup(a.phase.id)}`;$('#answer').innerHTML='Começar desafio <span>→</span>';$('#lesson-hint').textContent='5 energias por atividade. Se sair antes de concluir, elas são devolvidas.';hydrateMedia($('#lesson-content'));return;}if(a.index>=a.deck.length){finishAttempt();return;}const q=a.deck[a.index];a.selected=null;a.order=[];a.tries=0;a.checked=false;let body=`<div class="eyebrow">${a.phase.exam?'REVISÃO CUMULATIVA':'SUA VEZ'} · QUESTÃO ${a.index+1}</div><h2>${q.prompt}</h2>${q.audio?audioButtons(q.audio,true):''}${q.audioSequence?'<div class="audio-buttons"><button type="button" class="audio" data-quiz-sequence>◖)) Ouvir sequência</button><button type="button" class="audio slow-audio" data-quiz-sequence data-slow>0,7× · Devagar</button></div>':''}${q.diagram?diagram(q.diagram):''}`;if(q.type==='choice'||q.type==='listen'){body+=`<div class="options">${shuffled(q.options.map((text,i)=>({text,i}))).map(({text,i},index)=>`<button class="option" data-choice="${i}" aria-pressed="false"><span>${index+1}</span>${text}</button>`).join('')}</div>`;$('#answer').disabled=true;}else if(q.type==='input'){body+=`<form id="written-form"><label class="written-label" for="written-answer">Digite o termo usando letras comuns (romaji).</label><textarea id="written-answer" class="written-answer" rows="${Math.max(...q.answers.map(a=>a.length))>90?4:2}" autocomplete="off" autocapitalize="off" spellcheck="false" maxlength="600" placeholder="Escreva os termos na ordem pedida"></textarea><button type="submit" class="visually-hidden" tabindex="-1">Verificar resposta</button></form>`;$('#answer').disabled=true;}else{body+=`<p>Toque nos itens na ordem correta.</p><div id="order-picked" class="order-picked" aria-live="polite"></div><div class="order-options">${shuffled(q.items.map((text,i)=>({text,i}))).map(({text,i})=>`<button class="order-token" data-pick-order="${i}">${text}</button>`).join('')}</div><button class="text-button" id="order-reset" data-reset-order>Recomeçar a ordem</button>`;$('#answer').disabled=true;}$('#lesson-content').innerHTML=body;$('#answer').innerHTML='Verificar <span>→</span>';$('#lesson').scrollTop=0;}
function answer(){const a=active;if(!a)return;if(a.finished){const id=a.module.id;$('#lesson').close();go('module/'+id);return;}if(a.index<0){a.index=0;renderQuestion();return;}if(a.checked){a.index++;renderQuestion();return;}const q=a.deck[a.index];let right=false;if(q.type==='input'){const value=$('#written-answer').value.trim();if(!value)return;right=q.answers.some(x=>C.normalize(x)===C.normalize(value));}else if(q.type==='order'){if(a.order.length!==q.items.length)return;right=a.order.every((x,i)=>x===i);}else{if(a.selected===null)return;right=a.selected===q.answer;}a.tries++;if(right){stopAudio();DojoFeedback.success();if(a.tries===1)a.correct++;a.checked=true;document.querySelectorAll('#lesson-content .option,#lesson-content .order-token,#written-answer,#order-reset').forEach(el=>el.disabled=true);$('#feedback').className='';$('#feedback').textContent='Isso mesmo! '+q.why;$('#answer').innerHTML=a.index===a.deck.length-1?'Ver resultado <span>✦</span>':'Continuar <span>→</span>';$('#answer').disabled=false;}else{if(a.tries===1)a.wrong.push(q.id);$('#feedback').className='retry';$('#feedback').textContent='Vamos revisar. '+q.why+' Corrija para continuar; esta questão já entrou como revisão na nota.';if(q.type==='choice'||q.type==='listen'){const button=$(`[data-choice="${a.selected}"]`);button.classList.add('wrong');button.disabled=true;a.selected=null;$('#answer').disabled=true;}else if(q.type==='order')$('#answer').disabled=true;}}
function finishAttempt(){const a=active,result=C.record(state.learning,a.phase.id,a.correct,a.deck.length,a.wrong);a.finished=true;a.charged=false;state.game.pendingEnergy=false;const today=dayKey();state.rewards[today]??=[];const reward=result.passed&&!state.rewards[today].includes(a.phase.id)?20:0;if(reward){state.rewards[today].push(a.phase.id);state.xp+=reward;G.credit(state.game,reward);}if(result.passed&&!state.completed.includes(a.phase.id))state.completed.push(a.phase.id);if(!state.days.includes(today))state.days.push(today);state.sessions[today]=(state.sessions[today]||0)+1;save();DojoPush.practiced();stats();$('#lesson-bar').style.width='100%';$('#lesson-count').textContent=result.passed?'✓':'↻';const mistakes=a.wrong.map(id=>C.QUESTIONS[id].why);$('#lesson-content').innerHTML=`<div class="finish"><div class="result-emblem">${result.passed?'✓':'↻'}</div><div class="eyebrow">${result.passed?'FASE APROVADA':'É HORA DE REVISAR'}</div><h2>${result.passed?'Seu conhecimento deu mais um passo.':'Vamos fortalecer o que faltou.'}</h2><div class="finish-stats"><div><small>NOTA DE PRIMEIRA</small>${result.score}%</div><div><small>META DA FASE</small>${a.module.pass}%</div><div><small>XP</small>+${reward}</div></div><p>${result.passed?reward?'Você atingiu a meta da fase. Continue no seu ritmo!':'Fase aprovada. Os pontos desta fase já foram recebidos hoje.':`Foram ${a.correct} de ${a.deck.length} acertos de primeira. Revise abaixo e tente novamente quando quiser.`}</p>${mistakes.length?`<div class="review-notes"><h3>O que vale revisar</h3><ul>${mistakes.map(t=>`<li>${t}</li>`).join('')}</ul></div>`:''}<p class="week-note">${!result.passed&&result.entry.passed?'Esta revisão não apaga uma aprovação anterior.':result.passed&&a.phase.exam&&a.module.requiresSensei?'Agora mostre a prática ao sensei. A conferência libera o próximo módulo.':'A execução dos movimentos e a pronúncia são acompanhadas pelo sensei.'}</p></div>`;$('#answer').innerHTML='Voltar ao módulo <span>→</span>';$('#lesson-hint').textContent=result.passed?'Cada detalhe aprendido faz diferença.':'Sem a meta, a fase seguinte continua bloqueada.';}
function prefillMaterial(){const id=$('#media-phase')?.value,own=state.media[id]||{};if(!id)return;libraryPhase=id;$('#media-title').value=own.title||'';$('#media-description').value=own.description||'';$('#media-youtube').value=own.youtubeId?'https://www.youtube.com/watch?v='+own.youtubeId:'';}
document.addEventListener('click',async e=>{
const target=e.target;const sequenceButton=target.closest('[data-quiz-sequence]');if(sequenceButton&&active?.index>=0){const terms=active.deck[active.index]?.audioSequence;if(terms)speakSequence(terms,sequenceButton.hasAttribute('data-slow'));return;}const sectionLink=target.closest('[data-words-section]');if(sectionLink){e.preventDefault();document.getElementById(sectionLink.dataset.wordsSection)?.scrollIntoView({behavior:'smooth',block:'start'});return;}const addKihon=target.closest('[data-add-kihon-media]'),viewKihon=target.closest('[data-kihon-material]');if(addKihon&&!DojoAccounts.canManage()){go('account');return;}if(addKihon){go('library/'+addKihon.dataset.addKihonMedia);return;}if(viewKihon){go('kihon/'+viewKihon.dataset.kihonMaterial);return;}const track=target.closest('[data-track]'),approveTraining=target.closest('[data-approve-training]'),scrollCategory=target.closest('[data-category-scroll]');if(track){go('module/treino-'+track.dataset.track+'-'+state.game.belt);return;}if(approveTraining){if(!DojoAccounts.canManage()){toast('A conferência é exclusiva do administrador.');return;}if(!$('#training-observed').checked){toast('Confirme a observação da prática desta faixa.');return;}try{await DojoAccounts.approve(DojoAccounts.user.id,'grade-'+approveTraining.dataset.approveTraining,$('#training-note').value);T.approve(state.learning,state.game,Number(approveTraining.dataset.approveTraining),$('#training-note').value);save();render();toast('Prática registrada. A subida também depende dos XP no fechamento da semana.');}catch(error){toast(error.message);}return;}if(scrollCategory){e.preventDefault();document.getElementById('category-'+scrollCategory.dataset.categoryScroll).scrollIntoView({behavior:'smooth',block:'start'});return;}const kata=target.closest('[data-kata]'),addKata=target.closest('[data-add-kata-media]');if(kata){go('kata/'+kata.dataset.kata);return;}if(addKata&&!DojoAccounts.canManage()){go('account');return;}if(addKata){go('library/'+addKata.dataset.addKataMedia);return;}
const module=target.closest('[data-module]'),phase=target.closest('[data-phase]'),view=target.closest('[data-view]'),audio=target.closest('[data-speak]'),choice=target.closest('[data-choice]'),order=target.closest('[data-pick-order]');
if(module){go('module/'+module.dataset.module);return;}if(phase){startPhase(phase.dataset.phase);return;}if(view){go(view.dataset.view);return;}if(audio){speak(audio.dataset.speak,audio.hasAttribute('data-slow'));return;}
if(choice&&active&&!active.checked){active.selected=Number(choice.dataset.choice);document.querySelectorAll('#lesson-content .option').forEach(el=>{el.classList.toggle('selected',el===choice);el.setAttribute('aria-pressed',String(el===choice));});$('#answer').disabled=false;DojoFeedback.read(active.deck[active.index].options[active.selected]);return;}
if(order&&active&&!active.checked){const i=Number(order.dataset.pickOrder);if(active.order.includes(i))return;active.order.push(i);order.disabled=true;const q=active.deck[active.index];DojoFeedback.read(q.items[i]);$('#order-picked').innerHTML=active.order.map((x,index)=>`<span>${index+1}. ${q.items[x]}</span>`).join('');$('#answer').disabled=active.order.length!==q.items.length;return;}
if(target.closest('[data-reset-order]')&&active&&!active.checked){active.order=[];$('#order-picked').innerHTML='';document.querySelectorAll('[data-pick-order]').forEach(el=>el.disabled=false);$('#answer').disabled=true;return;}
if(target.closest('[data-review]')){const available=C.COURSE.flatMap(m=>m.phases).filter(p=>C.phaseUnlocked(state.learning,p.id)),weak=available.filter(p=>state.learning.phases[p.id]?.wrong?.length);const list=weak.length?weak:available;startPhase(list[Math.floor(Math.random()*list.length)].id);return;}
if(target.closest('[data-energy]')){openEnergy();return;}
const load=target.closest('[data-load-video]');if(load&&/^[A-Za-z0-9_-]{11}$/.test(load.dataset.loadVideo)){load.closest('.yt-placeholder').outerHTML=`<iframe class="lesson-video" src="https://www.youtube-nocookie.com/embed/${load.dataset.loadVideo}?rel=0" title="Vídeo de referência para esta fase" referrerpolicy="strict-origin-when-cross-origin" allow="encrypted-media; picture-in-picture; fullscreen" allowfullscreen></iframe>`;return;}
const preview=target.closest('[data-preview-material]');if(preview){const found=mediaTarget(preview.dataset.previewMaterial);go(found.kihon?'kihon/'+found.phase.id:found.kata?'kata/'+found.phase.id:'module/'+found.module.id);return;}
const approve=target.closest('[data-approve-module]');if(approve){if(!DojoAccounts.canManage()){toast('A conferência é exclusiva do administrador.');return;}const id=approve.dataset.approveModule;if(!$(`[data-confirm-observed="${id}"]`).checked){toast('Confirme a observação da prática antes de registrar.');return;}try{await DojoAccounts.approve(DojoAccounts.user.id,id,$(`[data-approval-note="${id}"]`).value);C.approve(state.learning,id,$(`[data-approval-note="${id}"]`).value);save();render();toast('Conferência prática registrada. A próxima etapa foi liberada.');}catch(error){toast(error.message);}return;}
if(target.closest('[data-export-links]')){exportLinks();return;}
const remove=target.closest('[data-remove-material]');if(remove){if(!DojoAccounts.canManage()){toast('Somente o administrador pode remover materiais.');return;}const id=remove.dataset.removeMaterial;$('#remove-material-confirm').innerHTML=`<p>Remover este material personalizado? A referência inicial da fase volta a aparecer.</p><button class="outline danger" data-confirm-remove="${esc(id)}">Sim, remover material</button><button class="text-button" data-cancel-remove>Cancelar</button>`;return;}
if(target.closest('[data-cancel-remove]')){$('#remove-material-confirm').innerHTML='';return;}
const confirm=target.closest('[data-confirm-remove]');if(confirm){if(!DojoAccounts.canManage())return;const id=confirm.dataset.confirmRemove,entry=state.media[id];if(DojoAccounts.configured){try{state.media=await DojoAccounts.removeMaterial(id);render();toast('Material removido da biblioteca do San Dojo.');}catch{toast('Não foi possível remover o material.');}return;}if(entry){if(entry.videoKey)await DojoMedia.remove(entry.videoKey);if(entry.imageKey)await DojoMedia.remove(entry.imageKey);delete state.media[id];save();render();toast('Material removido deste navegador.');}return;}
if(target.closest('[data-reset]')){$('#reset-confirm').innerHTML='<p>Reiniciar pontos, faixas e fases? Seus materiais da biblioteca serão preservados.</p><button class="outline danger" data-confirm-reset>Sim, reiniciar progresso</button><button class="text-button" data-cancel-reset>Cancelar</button>';return;}
if(target.closest('[data-cancel-reset]')){$('#reset-confirm').innerHTML='';return;}
if(target.closest('[data-confirm-reset]')){const media=state.media;state=defaults();state.media=media;save();render();toast('Progresso reiniciado. A biblioteca foi preservada.');}
});
document.addEventListener('submit',e=>{if(e.target.id==='media-form')saveMaterial(e);if(e.target.id==='written-form'){e.preventDefault();answer();}});
document.addEventListener('input',e=>{if(e.target.id==='kata-search'){kataSearch=e.target.value;filterKatas();}if(e.target.id==='written-answer'&&active&&!active.checked)$('#answer').disabled=!e.target.value.trim();});
document.addEventListener('change',e=>{if(e.target.id==='training-belt'){selectedTrainingBelt=Number(e.target.value);render();}if(e.target.id==='kata-family'){kataFamily=e.target.value;filterKatas();}if(e.target.id==='media-module'){libraryModule=e.target.value;const m=mediaGroupById(libraryModule);$('#media-phase').innerHTML=m.phases.map((p,i)=>`<option value="${p.id}">${i+1}. ${p.title}</option>`).join('');prefillMaterial();$('#media-video').value='';$('#media-image').value='';}if(e.target.id==='media-phase'){prefillMaterial();$('#media-video').value='';$('#media-image').value='';}if(e.target.id==='import-links')importLinks(e.target.files[0]);});
$('#answer').addEventListener('click',answer);$('#close-lesson').addEventListener('click',()=>$('#lesson').close());
$('#lesson').addEventListener('close',()=>{if(active?.charged&&!active.finished){G.refund(state.game);state.game.pendingEnergy=false;save();}active=null;stopAudio();render();});
$('#close-energy').addEventListener('click',()=>$('#energy-dialog').close());
window.addEventListener('hashchange',route);bootAccounts();
if(settledWeeks.length)toast('Uma nova semana começou. Confira sua faixa e sua meta.');
setInterval(()=>{if(!appReady)return;const settled=G.reconcile(state.game);if(settled.length){save();if(!$('#lesson').open)render();}stats();if($('#energy-dialog').open){const summary=$('#energy-content .energy-summary');if(summary)summary.outerHTML=energyMarkup();}},1000);

async function bootAccounts(){await DojoAccounts.ready;const A=DojoAccounts;if(A.user&&A.canStudy()&&!A.error){key="san-dojo-user-"+A.user.id;let own;try{own=await A.loadProgress();if(!own)own=JSON.parse(localStorage.getItem(key)||"null");}catch{A.syncMessage="Não foi possível carregar o progresso online. O salvamento online está pausado.";try{own=JSON.parse(localStorage.getItem(key)||"null");}catch{}}state={...defaults(),...(own&&Array.isArray(own.completed)&&Array.isArray(own.days)&&Number.isFinite(own.xp)?own:{})};state.media=A.materials;if(!state.game||state.game.version!==1)state.game=G.create();if(!state.learning||state.learning.version!==1)state.learning=C.initial();state.learning.approvals={};state.game.mastery={};for(const item of A.approvals){const entry={at:Date.parse(item.approved_at),note:item.note};state.learning.approvals[item.target_id]=entry;if(item.target_id.startsWith("grade-"))state.game.mastery[Number(item.target_id.slice(6))]=true;}state.game.requireMastery=true;state.game.masteryFromWeek??=G.weekKey();T.syncMastery(state.learning,state.game);G.reconcile(state.game);state.learning.availableBelt=state.game.belt;}appReady=true;route();save();window.DojoAds?.load();if(!A.configured||(A.localPreview&&!A.user)){const banner=document.createElement("div");banner.className="account-preview-banner";banner.textContent=A.configured?"Prévia local · login online em preparação · edição de materiais bloqueada":"Prévia local · contas ainda não conectadas · edição de materiais bloqueada";document.querySelector(".app").prepend(banner);}}

let sequenceDayBoundary=dayKey();setInterval(()=>{if(!appReady)return;const day=dayKey();if(day!==sequenceDayBoundary){sequenceDayBoundary=day;if(!$('#lesson').open&&['home','sequence'].includes(currentView))render();}},30000);
